def git_run(root: Path, *args: str) -> tuple[int, str]:
    """작업 폴더에서 git 을 실행한다(표준출력+오류를 합쳐 돌려준다)."""
    try:
        proc = subprocess.run(
            ["git", *args],
            cwd=str(root),
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as exc:
        return 1, str(exc)
    out = (proc.stdout or "") + (proc.stderr or "")
    return proc.returncode, out.strip()


